// 누군가 책 사이에 끼워둔 쪽지 — 그 책을 펼치면 나온다
(function seedMemos() {
  const put = (roomIdx, title, who, text) => {
    const R = ROOMS[roomIdx];
    for (const s of R.items) if (s.kind === 'shelf')
      for (const bk of s.books) if (bk.t === title) (bk.memos = bk.memos || []).push({ who, text });
  };
  put(0, '데미안', '엄마', '고등학교 때 네가 이 책 사달라고 조르던 게 생각나서 한 장 껴둔다.');
})();

